/** El texto tal como lo diría la imagen, para medir las reglas con una lectura perfecta. */
const plainText = (c) =>
  [c.content, c.second]
    .filter(Boolean)
    .map((k) =>
      contents[k].lines
        .map(
          (l, i) =>
            (contents[k].bullets && i ? "• " : "") + l.replaceAll(" | ", "  "),
        )
        .join("\n"),
    )
    .join("\n");

module.exports = { today, contents, cases, cuadrante, plainText };
